@Test
public void setConfigFromObject() {
    // GIVEN
    SimpleConfiguration object = new SimpleConfiguration();
    object.setBindHost("host");
    object.setClientAddress("address");
    object.setEnabled(true);
    object.setPort(5555);
    object.setWaitTime(600);
    object.setMyClass(this.getClass());
    OzoneConfiguration subject = new OzoneConfiguration();
    // WHEN
    subject.setFromObject(object);
    // THEN
    Assert.assertEquals(object.getBindHost(), subject.get("test.scm.client.bind.host"));
    Assert.assertEquals(object.getClientAddress(), subject.get("test.scm.client.address"));
    Assert.assertEquals(object.isEnabled(), subject.getBoolean("test.scm.client.enabled", false));
    Assert.assertEquals(object.getPort(), subject.getInt("test.scm.client.port", 0));
    Assert.assertEquals(TimeUnit.SECONDS.toMinutes(object.getWaitTime()), subject.getTimeDuration("test.scm.client.wait", 0, TimeUnit.MINUTES));
    Assert.assertEquals(this.getClass(), subject.getClass("test.scm.client.class", null));
}

