    Assert.assertNull(raftProperties.get("raft.grpc.tls.mutual_authn.enabled"));
    Assert.assertNull(raftProperties.get("raft.grpc.server.port"));
}

@Test
public void testCreateRaftGrpcPropertiesForServer() {
