        List<? extends Table.KeyValue<String, BlockData>> deletingBlocks = meta.getStore().getBlockDataTable().getRangeKVs(null, 100, MetadataKeyFilters.getDeletingKeyFilter());
        // Delete all blocks marked for deletion.
        BlockDeletingServiceTestImpl svc = getBlockDeletingService(containerSet, conf);
