        List<? extends Table.KeyValue<String, ChunkInfoList>> deletedBlocks = meta.getStore().getDeletedBlocksTable().getRangeKVs(null, 100);
        Assert.assertEquals(deletingBlocks.size(), deletedBlocks.size());
