        Iterator<? extends Table.KeyValue<String, ChunkInfoList>> deletedBlocksIter = deletedBlocks.iterator();
        while (deletingBlocksIter.hasNext() && deletedBlocksIter.hasNext()) {
            List<ContainerProtos.ChunkInfo> deletingChunks = deletingBlocksIter.next().getValue().getChunks();
            List<ContainerProtos.ChunkInfo> deletedChunks = deletedBlocksIter.next().getValue().asList();
            // On each element of each list, this call uses the equals method
            // for ChunkInfos generated by protobuf.
