@Test
public void testShutdown() throws Exception {
    long initialUsedSpace = 250;
    AtomicLong savedUsedSpace = new AtomicLong(initialUsedSpace);
    SpaceUsagePersistence persistence = inMemory(savedUsedSpace);
    SpaceUsageSource spaceUsage = fixed(500, 200);
    long expectedUsedSpace = spaceUsage.getUsedSpace();
    SpaceUsageCheckFactory factory = MockSpaceUsageCheckFactory.of(spaceUsage, Duration.ZERO, persistence);
    volumeBuilder.usageCheckFactory(factory);
    HddsVolume volume = volumeBuilder.build();
    assertEquals(initialUsedSpace, savedUsedSpace.get());
    assertEquals(expectedUsedSpace, volume.getUsedSpace());
    // Shutdown the volume.
    volume.shutdown();
    // Volume state should be "NON_EXISTENT" when volume is shutdown.
    assertEquals(HddsVolume.VolumeState.NON_EXISTENT, volume.getStorageState());
    // Volume should save scmUsed cache file once volume is shutdown
    assertEquals(expectedUsedSpace, savedUsedSpace.get());
    // Volume.getAvailable() should succeed even when usage thread
    // is shutdown.
    assertEquals(spaceUsage.getAvailable(), volume.getAvailable());
}

/**
 * Test {@link HddsVolumeChecker#checkVolume} propagates the
 * check to the delegate checker.
 *
 * @throws Exception
 */
@Test
public void testCheckOneVolume() throws Exception {
    LOG.info("Executing {}", testName.getMethodName());
    final HddsVolume volume = makeVolumes(1, expectedVolumeHealth).get(0);
    final HddsVolumeChecker checker = new HddsVolumeChecker(new OzoneConfiguration(), new FakeTimer());
    checker.setDelegateChecker(new DummyChecker());
    final AtomicLong numCallbackInvocations = new AtomicLong(0);
    /**
     * Request a check and ensure it triggered {@link HddsVolume#check}.
     */
    boolean result = checker.checkVolume(volume, (healthyVolumes, failedVolumes) -> {
        numCallbackInvocations.incrementAndGet();
        if (expectedVolumeHealth != null && expectedVolumeHealth != FAILED) {
            assertThat(healthyVolumes.size(), is(1));
            assertThat(failedVolumes.size(), is(0));
        } else {
            assertThat(healthyVolumes.size(), is(0));
            assertThat(failedVolumes.size(), is(1));
        }
    });
    GenericTestUtils.waitFor(() -> numCallbackInvocations.get() > 0, 5, 10000);
    // Ensure that the check was invoked at least once.
    verify(volume, times(1)).check(anyObject());
    if (result) {
        assertThat(numCallbackInvocations.get(), is(1L));
    }
}

/**
 * Test {@link HddsVolumeChecker#checkAllVolumes} propagates
 * checks for all volumes to the delegate checker.
 *
 * @throws Exception
 */
@Test
public void testCheckAllVolumes() throws Exception {
    LOG.info("Executing {}", testName.getMethodName());
    final List<HddsVolume> volumes = makeVolumes(NUM_VOLUMES, expectedVolumeHealth);
    final HddsVolumeChecker checker = new HddsVolumeChecker(new OzoneConfiguration(), new FakeTimer());
    checker.setDelegateChecker(new DummyChecker());
    Set<HddsVolume> failedVolumes = checker.checkAllVolumes(volumes);
    LOG.info("Got back {} failed volumes", failedVolumes.size());
    if (expectedVolumeHealth == null || expectedVolumeHealth == FAILED) {
        assertThat(failedVolumes.size(), is(NUM_VOLUMES));
    } else {
        assertTrue(failedVolumes.isEmpty());
    }
    // Ensure each volume's check() method was called exactly once.
    for (HddsVolume volume : volumes) {
        verify(volume, times(1)).check(anyObject());
    }
}

/**
 * Test {@link HddsVolumeChecker#checkAllVolumes} propagates
 * checks for all volumes to the delegate checker.
 *
 * @throws Exception
 */
@Test
public void testVolumeDeletion() throws Exception {
    LOG.info("Executing {}", testName.getMethodName());
    conf.setTimeDuration(DFSConfigKeysLegacy.DFS_DATANODE_DISK_CHECK_MIN_GAP_KEY, 0, TimeUnit.MILLISECONDS);
    DatanodeDetails datanodeDetails = ContainerTestUtils.createDatanodeDetails();
    OzoneContainer ozoneContainer = ContainerTestUtils.getOzoneContainer(datanodeDetails, conf);
    MutableVolumeSet volumeSet = ozoneContainer.getVolumeSet();
    ContainerSet containerSet = ozoneContainer.getContainerSet();
    HddsVolumeChecker volumeChecker = volumeSet.getVolumeChecker();
    volumeChecker.setDelegateChecker(new DummyChecker());
    File volParentDir = new File(folder.getRoot(), UUID.randomUUID().toString());
    volumeSet.addVolume(volParentDir.getPath());
    File volRootDir = new File(volParentDir, "hdds");
    int i = 0;
    for (ContainerDataProto.State state : ContainerDataProto.State.values()) {
        if (!state.equals(ContainerDataProto.State.INVALID)) {
            // add containers to the created volume
            Container container = ContainerTestUtils.getContainer(++i, layout, state);
            container.getContainerData().setVolume(volumeSet.getVolumeMap().get(volRootDir.getPath()));
            ((KeyValueContainerData) container.getContainerData()).setMetadataPath(volParentDir.getPath());
            containerSet.addContainer(container);
        }
    }
    // delete the volume directory
    FileUtils.deleteDirectory(volParentDir);
    Assert.assertEquals(2, volumeSet.getVolumesList().size());
    volumeSet.checkAllVolumes();
    // failed volume should be removed from volumeSet volume list
    Assert.assertEquals(1, volumeSet.getVolumesList().size());
    Assert.assertEquals(1, volumeSet.getFailedVolumesList().size());
    i = 0;
    for (ContainerDataProto.State state : ContainerDataProto.State.values()) {
        if (!state.equals(ContainerDataProto.State.INVALID)) {
            Assert.assertEquals(ContainerDataProto.State.UNHEALTHY, containerSet.getContainer(++i).getContainerState());
        }
    }
    ozoneContainer.stop();
}

@Test
public void testRRVolumeChoosingPolicy() throws Exception {
    HddsVolume hddsVolume1 = volumes.get(0);
    HddsVolume hddsVolume2 = volumes.get(1);
    Assert.assertEquals(100L, hddsVolume1.getAvailable());
    Assert.assertEquals(200L, hddsVolume2.getAvailable());
    // Test two rounds of round-robin choosing
    Assert.assertEquals(hddsVolume1, policy.chooseVolume(volumes, 0));
    Assert.assertEquals(hddsVolume2, policy.chooseVolume(volumes, 0));
    Assert.assertEquals(hddsVolume1, policy.chooseVolume(volumes, 0));
    Assert.assertEquals(hddsVolume2, policy.chooseVolume(volumes, 0));
    // The first volume has only 100L space, so the policy should
    // choose the second one in case we ask for more.
    Assert.assertEquals(hddsVolume2, policy.chooseVolume(volumes, 150));
    // Fail if no volume has enough space available
    try {
        policy.chooseVolume(volumes, Long.MAX_VALUE);
        Assert.fail();
    } catch (IOException e) {
        // Passed.
    }
}

