@Test
public void concurrentReadOfSameFile() throws Exception {
    String s = "Hello World";
    byte[] array = s.getBytes();
    ChunkBuffer data = ChunkBuffer.wrap(ByteBuffer.wrap(array));
    Path tempFile = Files.createTempFile(PREFIX, "concurrent");
    try {
        long len = data.limit();
        long offset = 0;
        File file = tempFile.toFile();
        VolumeIOStats stats = new VolumeIOStats();
        ChunkUtils.writeData(file, data, offset, len, stats, true);
        int threads = 10;
        ExecutorService executor = new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS, new LinkedBlockingQueue<>());
        AtomicInteger processed = new AtomicInteger();
        AtomicBoolean failed = new AtomicBoolean();
        for (int i = 0; i < threads; i++) {
            final int threadNumber = i;
            executor.execute(() -> {
                try {
                    ByteBuffer readBuffer = ByteBuffer.allocate((int) len);
                    ChunkUtils.readData(file, readBuffer, offset, len, stats);
                    LOG.info("Read data ({}): {}", threadNumber, new String(readBuffer.array()));
                    if (!Arrays.equals(array, readBuffer.array())) {
                        failed.set(true);
                    }
                    assertEquals(len, readBuffer.remaining());
                } catch (Exception e) {
                    LOG.error("Failed to read data ({})", threadNumber, e);
                    failed.set(true);
                }
                processed.incrementAndGet();
            });
        }
        try {
            GenericTestUtils.waitFor(() -> processed.get() == threads, 100, (int) TimeUnit.SECONDS.toMillis(5));
        } finally {
            executor.shutdownNow();
        }
        assertFalse(failed.get());
    } finally {
        Files.deleteIfExists(tempFile);
    }
}

@Test
public void concurrentProcessing() throws Exception {
    final int perThreadWait = 1000;
    final int maxTotalWait = 5000;
    int threads = 20;
    List<Path> paths = new LinkedList<>();
    try {
        ExecutorService executor = new ThreadPoolExecutor(threads, threads, 0, TimeUnit.SECONDS, new LinkedBlockingQueue<>());
        AtomicInteger processed = new AtomicInteger();
        for (int i = 0; i < threads; i++) {
            Path path = Files.createTempFile(PREFIX, String.valueOf(i));
            paths.add(path);
            executor.execute(() -> {
                ChunkUtils.processFileExclusively(path, () -> {
                    try {
                        Thread.sleep(perThreadWait);
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                    processed.incrementAndGet();
                    return null;
                });
            });
        }
        try {
            GenericTestUtils.waitFor(() -> processed.get() == threads, 100, maxTotalWait);
        } finally {
            executor.shutdownNow();
        }
    } finally {
        for (Path path : paths) {
            FileUtils.deleteQuietly(path.toFile());
        }
    }
}

