    builder.addCRLEntry(x509CertificateHolder.getSerialNumber(), now, CRLReason.cACompromise);
    JcaContentSignerBuilder contentSignerBuilder = new JcaContentSignerBuilder(securityConfig.getSignatureAlgo());
    contentSignerBuilder.setProvider(securityConfig.getProvider());
    PrivateKey privateKey = keyPair.getPrivate();
    X509CRLHolder cRLHolder = builder.build(contentSignerBuilder.build(privateKey));
    CRLCodec crlCodec = new CRLCodec(securityConfig);
    crlCodec.writeCRL(cRLHolder, this.securityConfig.getCrlName(), true);
    X509CRLEntryHolder entryHolder = cRLHolder.getRevokedCertificate(BigInteger.ONE);
    assertNotNull(entryHolder);
    // verify file generation
    File crlFile = Paths.get(crlCodec.getLocation().toString(), this.securityConfig.getCrlName()).toFile();
    assertTrue(crlFile.exists());
    try (BufferedReader reader = new BufferedReader(new FileReader(crlFile))) {
        // Verify contents of the file
        String header = reader.readLine();
        assertEquals("-----BEGIN X509 CRL-----", header);
        String footer = null;
        String line = null;
        while ((line = reader.readLine()) != null) {
            footer = line;
        }
        assertEquals("-----END X509 CRL-----", footer);
    }
}

