@Test
public void testAllFieldsAreExpected() throws SCMSecurityException, NoSuchProviderException, NoSuchAlgorithmException, CertificateException, SignatureException, InvalidKeyException, IOException {
    LocalDate notBefore = LocalDate.now();
    LocalDate notAfter = notBefore.plus(365, ChronoUnit.DAYS);
    String clusterID = UUID.randomUUID().toString();
    String scmID = UUID.randomUUID().toString();
    String subject = "testRootCert";
    HDDSKeyGenerator keyGen = new HDDSKeyGenerator(securityConfig.getConfiguration());
    KeyPair keyPair = keyGen.generateKey();
    SelfSignedCertificate.Builder builder = SelfSignedCertificate.newBuilder().setBeginDate(notBefore).setEndDate(notAfter).setClusterID(clusterID).setScmID(scmID).setSubject(subject).setKey(keyPair).setConfiguration(conf);
    X509CertificateHolder certificateHolder = builder.build();
    //Assert that we indeed have a self signed certificate.
    Assert.assertEquals(certificateHolder.getIssuer(), certificateHolder.getSubject());
    // Make sure that NotBefore is before the current Date
    Date invalidDate = java.sql.Date.valueOf(notBefore.minus(1, ChronoUnit.DAYS));
    Assert.assertFalse(certificateHolder.getNotBefore().before(invalidDate));
    //Make sure the end date is honored.
    invalidDate = java.sql.Date.valueOf(notAfter.plus(1, ChronoUnit.DAYS));
    Assert.assertFalse(certificateHolder.getNotAfter().after(invalidDate));
    // Check the Subject Name and Issuer Name is in the expected format.
    String dnName = String.format(SelfSignedCertificate.getNameFormat(), subject, scmID, clusterID);
    Assert.assertEquals(certificateHolder.getIssuer().toString(), dnName);
    Assert.assertEquals(certificateHolder.getSubject().toString(), dnName);
    // We did not ask for this Certificate to be a CertificateServer
    // certificate, hence that
    // extension should be null.
    Assert.assertNull(certificateHolder.getExtension(Extension.basicConstraints));
    // Extract the Certificate and verify that certificate matches the public
    // key.
    X509Certificate cert = new JcaX509CertificateConverter().getCertificate(certificateHolder);
    cert.verify(keyPair.getPublic());
}

@Test
public void testCACert() throws SCMSecurityException, NoSuchProviderException, NoSuchAlgorithmException, IOException, CertificateException {
    LocalDate notBefore = LocalDate.now();
    LocalDate notAfter = notBefore.plus(365, ChronoUnit.DAYS);
    String clusterID = UUID.randomUUID().toString();
    String scmID = UUID.randomUUID().toString();
    String subject = "testRootCert";
    HDDSKeyGenerator keyGen = new HDDSKeyGenerator(securityConfig.getConfiguration());
    KeyPair keyPair = keyGen.generateKey();
    SelfSignedCertificate.Builder builder = SelfSignedCertificate.newBuilder().setBeginDate(notBefore).setEndDate(notAfter).setClusterID(clusterID).setScmID(scmID).setSubject(subject).setKey(keyPair).setConfiguration(conf).makeCA();
    try {
        DomainValidator validator = DomainValidator.getInstance();
        // Add all valid ips.
        OzoneSecurityUtil.getValidInetsForCurrentHost().forEach(ip -> {
            builder.addIpAddress(ip.getHostAddress());
            if (validator.isValid(ip.getCanonicalHostName())) {
                builder.addDnsName(ip.getCanonicalHostName());
            }
        });
    } catch (IOException e) {
        throw new org.apache.hadoop.hdds.security.x509.exceptions.CertificateException("Error while adding ip to CA self signed certificate", e, CSR_ERROR);
    }
    X509CertificateHolder certificateHolder = builder.build();
    // This time we asked for a CertificateServer Certificate, make sure that
    // extension is
    // present and valid.
    Extension basicExt = certificateHolder.getExtension(Extension.basicConstraints);
    Assert.assertNotNull(basicExt);
    Assert.assertTrue(basicExt.isCritical());
    // Since this code assigns ONE for the root certificate, we check if the
    // serial number is the expected number.
    Assert.assertEquals(certificateHolder.getSerialNumber(), BigInteger.ONE);
    CertificateCodec codec = new CertificateCodec(securityConfig, "scm");
    String pemString = codec.getPEMEncodedString(certificateHolder);
    File basePath = temporaryFolder.newFolder();
    if (!basePath.exists()) {
        Assert.assertTrue(basePath.mkdirs());
    }
    codec.writeCertificate(basePath.toPath(), "pemcertificate.crt", pemString, false);
    X509CertificateHolder loadedCert = codec.readCertificate(basePath.toPath(), "pemcertificate.crt");
    assertNotNull(loadedCert);
    assertEquals(certificateHolder.getSerialNumber(), loadedCert.getSerialNumber());
}

@Test
public void testInvalidParamFails() throws SCMSecurityException, NoSuchProviderException, NoSuchAlgorithmException, IOException {
    LocalDate notBefore = LocalDate.now();
    LocalDate notAfter = notBefore.plus(365, ChronoUnit.DAYS);
    String clusterID = UUID.randomUUID().toString();
    String scmID = UUID.randomUUID().toString();
    String subject = "testRootCert";
    HDDSKeyGenerator keyGen = new HDDSKeyGenerator(securityConfig.getConfiguration());
    KeyPair keyPair = keyGen.generateKey();
    SelfSignedCertificate.Builder builder = SelfSignedCertificate.newBuilder().setBeginDate(notBefore).setEndDate(notAfter).setClusterID(clusterID).setScmID(scmID).setSubject(subject).setConfiguration(conf).setKey(keyPair).makeCA();
    try {
        builder.setKey(null);
        builder.build();
        Assert.fail("Null Key should have failed.");
    } catch (NullPointerException | IllegalArgumentException e) {
        builder.setKey(keyPair);
    }
    // Now try with Blank Subject.
    try {
        builder.setSubject("");
        builder.build();
        Assert.fail("Null/Blank Subject should have thrown.");
    } catch (IllegalArgumentException e) {
        builder.setSubject(subject);
    }
    // Now try with blank/null SCM ID
    try {
        builder.setScmID(null);
        builder.build();
        Assert.fail("Null/Blank SCM ID should have thrown.");
    } catch (IllegalArgumentException e) {
        builder.setScmID(scmID);
    }
    // Now try with blank/null SCM ID
    try {
        builder.setClusterID(null);
        builder.build();
        Assert.fail("Null/Blank Cluster ID should have thrown.");
    } catch (IllegalArgumentException e) {
        builder.setClusterID(clusterID);
    }
    // Swap the Begin and End Date and verify that we cannot create a
    // certificate like that.
    try {
        builder.setBeginDate(notAfter);
        builder.setEndDate(notBefore);
        builder.build();
        Assert.fail("Illegal dates should have thrown.");
    } catch (IllegalArgumentException e) {
        builder.setBeginDate(notBefore);
        builder.setEndDate(notAfter);
    }
    try {
        KeyPair newKey = keyGen.generateKey();
        KeyPair wrongKey = new KeyPair(newKey.getPublic(), keyPair.getPrivate());
        builder.setKey(wrongKey);
        X509CertificateHolder certificateHolder = builder.build();
        X509Certificate cert = new JcaX509CertificateConverter().getCertificate(certificateHolder);
        cert.verify(wrongKey.getPublic());
        Assert.fail("Invalid Key, should have thrown.");
    } catch (SCMSecurityException | CertificateException | SignatureException | InvalidKeyException e) {
        builder.setKey(keyPair);
    }
    // Assert that we can create a certificate with all sane params.
    Assert.assertNotNull(builder.build());
}

