@Test
public void testDowngrade() throws Exception {
    // Write data to current DB which has 6 column families at the time of
    // writing this test.
    for (String family : families) {
        try (Table table = rdbStore.getTable(family)) {
            byte[] key = family.getBytes(StandardCharsets.UTF_8);
            byte[] value = RandomStringUtils.random(10).getBytes(StandardCharsets.UTF_8);
            table.put(key, value);
        }
    }
    // Close current DB.
    rdbStore.close();
    // Reopen DB with the last column family removed.
    options = new DBOptions();
    options.setCreateIfMissing(true);
    options.setCreateMissingColumnFamilies(true);
    configSet = new HashSet<>();
    List<String> familiesMinusOne = families.subList(0, families.size() - 1);
    for (String name : familiesMinusOne) {
        TableConfig newConfig = new TableConfig(name, new ColumnFamilyOptions());
        configSet.add(newConfig);
    }
    rdbStore = new RDBStore(rdbStore.getDbLocation(), options, configSet);
    for (String family : familiesMinusOne) {
        try (Table table = rdbStore.getTable(family)) {
            Assert.assertNotNull(family + "is null", table);
            Object val = table.get(family.getBytes(StandardCharsets.UTF_8));
            Assert.assertNotNull(val);
        }
    }
    // Technically the extra column family should also be open, even though
    // we do not use it.
    String extraFamily = families.get(families.size() - 1);
    try (Table table = rdbStore.getTable(extraFamily)) {
        Assert.assertNotNull(extraFamily + "is null", table);
        Object val = table.get(extraFamily.getBytes(StandardCharsets.UTF_8));
        Assert.assertNotNull(val);
    }
}

@Test
public void testForeachRemainingCallsConsumerWithAllElements() {
    when(rocksDBIteratorMock.isValid()).thenReturn(true, true, true, true, true, true, true, false);
    when(rocksDBIteratorMock.key()).thenReturn(new byte[] { 0x00 }, new byte[] { 0x00 }, new byte[] { 0x01 }, new byte[] { 0x02 }).thenThrow(new NoSuchElementException());
    when(rocksDBIteratorMock.value()).thenReturn(new byte[] { 0x7f }, new byte[] { 0x7f }, new byte[] { 0x7e }, new byte[] { 0x7d }).thenThrow(new NoSuchElementException());
    Consumer<ByteArrayKeyValue> consumerStub = mock(Consumer.class);
    RDBStoreIterator iter = new RDBStoreIterator(rocksDBIteratorMock);
    iter.forEachRemaining(consumerStub);
    ArgumentCaptor<ByteArrayKeyValue> capture = ArgumentCaptor.forClass(ByteArrayKeyValue.class);
    verify(consumerStub, times(3)).accept(capture.capture());
    assertArrayEquals(new byte[] { 0x00 }, capture.getAllValues().get(0).getKey());
    assertArrayEquals(new byte[] { 0x7f }, capture.getAllValues().get(0).getValue());
    assertArrayEquals(new byte[] { 0x01 }, capture.getAllValues().get(1).getKey());
    assertArrayEquals(new byte[] { 0x7e }, capture.getAllValues().get(1).getValue());
    assertArrayEquals(new byte[] { 0x02 }, capture.getAllValues().get(2).getKey());
    assertArrayEquals(new byte[] { 0x7d }, capture.getAllValues().get(2).getValue());
}

