public void testIterator() throws Exception {
    OzoneConfiguration conf = new OzoneConfiguration();
    File dbDir = GenericTestUtils.getRandomizedTestDir();
    MetadataStore dbStore = MetadataStoreBuilder.newBuilder().setConf(conf).setCreateIfMissing(true).setDbFile(dbDir).setDBType(storeImpl).build();
    //As database is empty, check whether iterator is working as expected or
    // not.
