    assertFalse(metaStoreIterator.hasNext());
    try {
        metaStoreIterator.next();
        fail("testIterator failed");
    } catch (NoSuchElementException ex) {
        GenericTestUtils.assertExceptionContains("Store has no more elements", ex);
