/**
 * Asserts that a single node moves from Healthy to stale node, then from
 * stale node to dead node if it misses enough heartbeats.
 *
 * @throws IOException
 * @throws InterruptedException
 * @throws TimeoutException
 */
@Test
public void testScmDetectStaleAndDeadNode() throws IOException, InterruptedException, AuthenticationException {
    final int interval = 100;
    final int nodeCount = 10;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, interval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, 1, SECONDS);
    conf.setTimeDuration(OZONE_SCM_STALENODE_INTERVAL, 3, SECONDS);
    conf.setTimeDuration(OZONE_SCM_DEADNODE_INTERVAL, 6, SECONDS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        List<DatanodeDetails> nodeList = createNodeSet(nodeManager, nodeCount);
        DatanodeDetails staleNode = TestUtils.createRandomDatanodeAndRegister(nodeManager);
        // Heartbeat once
        nodeManager.processHeartbeat(staleNode);
        // Heartbeat all other nodes.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds .. and heartbeat good nodes again.
        Thread.sleep(2 * 1000);
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        // Wait for 2 seconds, wait a total of 4 seconds to make sure that the
        // node moves into stale state.
        Thread.sleep(2 * 1000);
        List<DatanodeDetails> staleNodeList = nodeManager.getNodes(STALE);
        assertEquals("Expected to find 1 stale node", 1, nodeManager.getNodeCount(STALE));
        assertEquals("Expected to find 1 stale node", 1, staleNodeList.size());
        assertEquals("Stale node is not the expected ID", staleNode.getUuid(), staleNodeList.get(0).getUuid());
        Thread.sleep(1000);
        // heartbeat good nodes again.
        for (DatanodeDetails dn : nodeList) {
            nodeManager.processHeartbeat(dn);
        }
        //  6 seconds is the dead window for this test , so we wait a total of
        // 7 seconds to make sure that the node moves into dead state.
        Thread.sleep(2 * 1000);
        // the stale node has been removed
        staleNodeList = nodeManager.getNodes(STALE);
        assertEquals("Expected to find 1 stale node", 0, nodeManager.getNodeCount(STALE));
        assertEquals("Expected to find 1 stale node", 0, staleNodeList.size());
        // Check for the dead node now.
        List<DatanodeDetails> deadNodeList = nodeManager.getNodes(DEAD);
        assertEquals("Expected to find 1 dead node", 1, nodeManager.getNodeCount(DEAD));
        assertEquals("Expected to find 1 dead node", 1, deadNodeList.size());
        assertEquals("Dead node is not the expected ID", staleNode.getUuid(), deadNodeList.get(0).getUuid());
    }
}

/**
 * Simulate a JVM Pause by pausing the health check process
 * Ensure that none of the nodes with heartbeats become Dead or Stale.
 * @throws IOException
 * @throws InterruptedException
 * @throws AuthenticationException
 */
@Test
public void testScmHandleJvmPause() throws IOException, InterruptedException, AuthenticationException {
    // milliseconds
    final int healthCheckInterval = 200;
    // seconds
    final int heartbeatInterval = 1;
    // seconds
    final int staleNodeInterval = 3;
    // seconds
    final int deadNodeInterval = 6;
    ScheduledFuture schedFuture;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, healthCheckInterval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, heartbeatInterval, SECONDS);
    conf.setTimeDuration(OZONE_SCM_STALENODE_INTERVAL, staleNodeInterval, SECONDS);
    conf.setTimeDuration(OZONE_SCM_DEADNODE_INTERVAL, deadNodeInterval, SECONDS);
    try (SCMNodeManager nodeManager = createNodeManager(conf)) {
        DatanodeDetails node1 = TestUtils.createRandomDatanodeAndRegister(nodeManager);
        DatanodeDetails node2 = TestUtils.createRandomDatanodeAndRegister(nodeManager);
        nodeManager.processHeartbeat(node1);
        nodeManager.processHeartbeat(node2);
        // Sleep so that heartbeat processing thread gets to run.
        Thread.sleep(1000);
        //Assert all nodes are healthy.
        assertEquals(2, nodeManager.getAllNodes().size());
        assertEquals(2, nodeManager.getNodeCount(HEALTHY));
        /**
         * Simulate a JVM Pause and subsequent handling in following steps:
         * Step 1 : stop heartbeat check process for stale node interval
         * Step 2 : resume heartbeat check
         * Step 3 : wait for 1 iteration of heartbeat check thread
         * Step 4 : retrieve the state of all nodes - assert all are HEALTHY
         * Step 5 : heartbeat for node1
         * [TODO : what if there is scheduling delay of test thread in Step 5?]
         * Step 6 : wait for some time to allow iterations of check process
         * Step 7 : retrieve the state of all nodes -  assert node2 is STALE
         * and node1 is HEALTHY
         */
        // Step 1 : stop health check process (simulate JVM pause)
        nodeManager.pauseHealthCheck();
        Thread.sleep(MILLISECONDS.convert(staleNodeInterval, SECONDS));
        // Step 2 : resume health check
        assertTrue("Unexpected, already skipped heartbeat checks", (nodeManager.getSkippedHealthChecks() == 0));
        schedFuture = nodeManager.unpauseHealthCheck();
        // Step 3 : wait for 1 iteration of health check
        try {
            schedFuture.get();
            assertTrue("We did not skip any heartbeat checks", nodeManager.getSkippedHealthChecks() > 0);
        } catch (ExecutionException e) {
            assertEquals("Unexpected exception waiting for Scheduled Health Check", 0, 1);
        }
        // Step 4 : all nodes should still be HEALTHY
        assertEquals(2, nodeManager.getAllNodes().size());
        assertEquals(2, nodeManager.getNodeCount(HEALTHY));
        // Step 5 : heartbeat for node1
        nodeManager.processHeartbeat(node1);
        // Step 6 : wait for health check process to run
        Thread.sleep(1000);
        // Step 7 : node2 should transition to STALE
        assertEquals(1, nodeManager.getNodeCount(HEALTHY));
        assertEquals(1, nodeManager.getNodeCount(STALE));
    }
}

