@Test
public void testPipelineReload() throws IOException {
    SCMPipelineManager pipelineManager = new SCMPipelineManager(conf, nodeManager, scmMetadataStore.getPipelineTable(), new EventQueue());
    pipelineManager.allowPipelineCreation();
    PipelineProvider mockRatisProvider = new MockRatisPipelineProvider(nodeManager, pipelineManager.getStateManager(), conf);
    pipelineManager.setPipelineProvider(HddsProtos.ReplicationType.RATIS, mockRatisProvider);
    int pipelineNum = 5;
    Set<Pipeline> pipelines = new HashSet<>();
    for (int i = 0; i < pipelineNum; i++) {
        Pipeline pipeline = pipelineManager.createPipeline(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE);
        pipelines.add(pipeline);
    }
    pipelineManager.close();
    // new pipeline manager should be able to load the pipelines from the db
    pipelineManager = new SCMPipelineManager(conf, nodeManager, scmMetadataStore.getPipelineTable(), new EventQueue());
    pipelineManager.allowPipelineCreation();
    mockRatisProvider = new MockRatisPipelineProvider(nodeManager, pipelineManager.getStateManager(), conf);
