@Test
public void testDelayedEventNotification() throws Exception {
    List<SafeModeStatus> delayedSafeModeEvents = new ArrayList<>();
    List<SafeModeStatus> safeModeEvents = new ArrayList<>();
    //given
    EventQueue eventQueue = new EventQueue();
    eventQueue.addHandler(SCMEvents.SAFE_MODE_STATUS, (safeModeStatus, publisher) -> safeModeEvents.add(safeModeStatus));
    eventQueue.addHandler(SCMEvents.DELAYED_SAFE_MODE_STATUS, (safeModeStatus, publisher) -> delayedSafeModeEvents.add(safeModeStatus));
    OzoneConfiguration ozoneConfiguration = new OzoneConfiguration();
    ozoneConfiguration.setTimeDuration(HddsConfigKeys.HDDS_SCM_WAIT_TIME_AFTER_SAFE_MODE_EXIT, 3, TimeUnit.SECONDS);
    ozoneConfiguration.setBoolean(HddsConfigKeys.HDDS_SCM_SAFEMODE_PIPELINE_CREATION, false);
    scmSafeModeManager = new SCMSafeModeManager(ozoneConfiguration, containers, null, eventQueue);
    //when
    scmSafeModeManager.setInSafeMode(true);
    scmSafeModeManager.setPreCheckComplete(true);
    scmSafeModeManager.emitSafeModeStatus();
    eventQueue.processAll(1000L);
    //then
    Assert.assertEquals(1, delayedSafeModeEvents.size());
    Assert.assertEquals(1, safeModeEvents.size());
    //when
    scmSafeModeManager.setInSafeMode(false);
    scmSafeModeManager.setPreCheckComplete(true);
    scmSafeModeManager.emitSafeModeStatus();
    eventQueue.processAll(1000L);
    //then
    Assert.assertEquals(2, safeModeEvents.size());
    //delayed messages are not yet sent (unless JVM is paused for 3 seconds)
    Assert.assertEquals(1, delayedSafeModeEvents.size());
    //event will be triggered after 3 seconds (see previous config)
    GenericTestUtils.waitFor(() -> delayedSafeModeEvents.size() == 2, 300, 6000);
}

@Test
public void testSafeModeExitRule() throws Exception {
    containers = new ArrayList<>();
    int numContainers = 100;
    containers.addAll(HddsTestUtils.getContainerInfo(numContainers));
    // Assign open state to containers to be included in the safe mode
    // container list
    for (ContainerInfo container : containers) {
        container.setState(HddsProtos.LifeCycleState.CLOSED);
    }
    scmSafeModeManager = new SCMSafeModeManager(config, containers, null, queue);
    long cutOff = (long) Math.ceil(numContainers * config.getDouble(HddsConfigKeys.HDDS_SCM_SAFEMODE_THRESHOLD_PCT, HddsConfigKeys.HDDS_SCM_SAFEMODE_THRESHOLD_PCT_DEFAULT));
    Assert.assertEquals(cutOff, scmSafeModeManager.getSafeModeMetrics().getNumContainerWithOneReplicaReportedThreshold().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(0, 25), 0.25);
    Assert.assertEquals(25, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(25, 50), 0.50);
    Assert.assertEquals(50, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(50, 75), 0.75);
    Assert.assertEquals(75, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    assertTrue(scmSafeModeManager.getInSafeMode());
    testContainerThreshold(containers.subList(75, 100), 1.0);
    Assert.assertEquals(100, scmSafeModeManager.getSafeModeMetrics().getCurrentContainersWithOneReplicaReportedCount().value());
    GenericTestUtils.waitFor(() -> {
        return !scmSafeModeManager.getInSafeMode();
    }, 100, 1000 * 5);
}

