@Test
public void testPipelinesNotCreatedUntilPreCheckPasses() throws Exception {
    int numOfDns = 5;
    // enable pipeline check
    config.setBoolean(HddsConfigKeys.HDDS_SCM_SAFEMODE_PIPELINE_AVAILABILITY_CHECK, true);
    config.setInt(HddsConfigKeys.HDDS_SCM_SAFEMODE_MIN_DATANODE, numOfDns);
    config.setBoolean(HddsConfigKeys.HDDS_SCM_SAFEMODE_PIPELINE_CREATION, true);
    MockNodeManager nodeManager = new MockNodeManager(true, numOfDns);
    String storageDir = GenericTestUtils.getTempPath(TestSCMSafeModeManager.class.getName() + UUID.randomUUID());
    config.set(HddsConfigKeys.OZONE_METADATA_DIRS, storageDir);
    // enable pipeline check
    config.setBoolean(HddsConfigKeys.HDDS_SCM_SAFEMODE_PIPELINE_AVAILABILITY_CHECK, true);
    SCMPipelineManager pipelineManager = new SCMPipelineManager(config, nodeManager, scmMetadataStore.getPipelineTable(), queue);
    PipelineProvider mockRatisProvider = new MockRatisPipelineProvider(nodeManager, pipelineManager.getStateManager(), config, true);
    pipelineManager.setPipelineProvider(HddsProtos.ReplicationType.RATIS, mockRatisProvider);
    SafeModeEventHandler smHandler = new SafeModeEventHandler();
    queue.addHandler(SCMEvents.SAFE_MODE_STATUS, smHandler);
    scmSafeModeManager = new SCMSafeModeManager(config, containers, pipelineManager, queue);
    // Assert SCM is in Safe mode.
    assertTrue(scmSafeModeManager.getInSafeMode());
    // Register all DataNodes except last one and assert SCM is in safe mode.
    for (int i = 0; i < numOfDns - 1; i++) {
        queue.fireEvent(SCMEvents.NODE_REGISTRATION_CONT_REPORT, HddsTestUtils.createNodeRegistrationContainerReport(containers));
        assertTrue(scmSafeModeManager.getInSafeMode());
        assertFalse(scmSafeModeManager.getPreCheckComplete());
    }
    queue.processAll(5000);
    Assert.assertEquals(0, smHandler.getInvokedCount());
    // Register last DataNode and check that the SafeModeEvent gets fired, but
    // safemode is still enabled with preCheck completed.
    queue.fireEvent(SCMEvents.NODE_REGISTRATION_CONT_REPORT, HddsTestUtils.createNodeRegistrationContainerReport(containers));
    queue.processAll(5000);
    Assert.assertEquals(1, smHandler.getInvokedCount());
    Assert.assertEquals(true, smHandler.getPreCheckComplete());
    Assert.assertEquals(true, smHandler.getIsInSafeMode());
    // Create a pipeline and ensure safemode is exited.
    pipelineManager.allowPipelineCreation();
    Pipeline pipeline = pipelineManager.createPipeline(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE);
    firePipelineEvent(pipelineManager, pipeline);
    queue.processAll(5000);
    Assert.assertEquals(2, smHandler.getInvokedCount());
    Assert.assertEquals(true, smHandler.getPreCheckComplete());
    Assert.assertEquals(false, smHandler.getIsInSafeMode());
}

@Test
public void testSortDatanodes() throws Exception {
    List<String> nodes = new ArrayList();
    nodeManager.getAllNodes().stream().forEach(node -> nodes.add(node.getNetworkName()));
    // sort normal datanodes
    String client;
    client = nodes.get(0);
    List<DatanodeDetails> datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // illegal client 1
    client += "X";
    datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // illegal client 2
    client = "/default-rack";
    datanodeDetails = server.sortDatanodes(nodes, client);
    System.out.println("client = " + client);
    datanodeDetails.stream().forEach(node -> System.out.println(node.toString()));
    Assert.assertTrue(datanodeDetails.size() == nodeCount);
    // unknown node to sort
    nodes.add(UUID.randomUUID().toString());
    ScmBlockLocationProtocolProtos.SortDatanodesRequestProto request = ScmBlockLocationProtocolProtos.SortDatanodesRequestProto.newBuilder().addAllNodeNetworkName(nodes).setClient(client).build();
    ScmBlockLocationProtocolProtos.SortDatanodesResponseProto resp = service.sortDatanodes(request);
    Assert.assertTrue(resp.getNodeList().size() == nodeCount);
    System.out.println("client = " + client);
    resp.getNodeList().stream().forEach(node -> System.out.println(node.getNetworkName()));
    // all unknown nodes
    nodes.clear();
    nodes.add(UUID.randomUUID().toString());
    nodes.add(UUID.randomUUID().toString());
    nodes.add(UUID.randomUUID().toString());
    request = ScmBlockLocationProtocolProtos.SortDatanodesRequestProto.newBuilder().addAllNodeNetworkName(nodes).setClient(client).build();
    resp = service.sortDatanodes(request);
    System.out.println("client = " + client);
    Assert.assertTrue(resp.getNodeList().size() == 0);
    resp.getNodeList().stream().forEach(node -> System.out.println(node.getNetworkName()));
}

@Test
public void testSCMContainerMetrics() {
    SCMMXBean scmmxBean = mock(SCMMXBean.class);
    Map<String, Integer> stateInfo = new HashMap<String, Integer>() {

        {
            put(HddsProtos.LifeCycleState.OPEN.toString(), 2);
            put(HddsProtos.LifeCycleState.CLOSING.toString(), 3);
            put(HddsProtos.LifeCycleState.QUASI_CLOSED.toString(), 4);
            put(HddsProtos.LifeCycleState.CLOSED.toString(), 5);
            put(HddsProtos.LifeCycleState.DELETING.toString(), 6);
            put(HddsProtos.LifeCycleState.DELETED.toString(), 7);
        }
    };
    when(scmmxBean.getContainerStateCount()).thenReturn(stateInfo);
    MetricsRecordBuilder mb = mock(MetricsRecordBuilder.class);
    when(mb.addGauge(any(MetricsInfo.class), anyInt())).thenReturn(mb);
    MetricsCollector metricsCollector = mock(MetricsCollector.class);
    when(metricsCollector.addRecord(anyString())).thenReturn(mb);
    SCMContainerMetrics containerMetrics = new SCMContainerMetrics(scmmxBean);
    containerMetrics.getMetrics(metricsCollector, true);
    verify(mb, times(1)).addGauge(Interns.info("OpenContainers", "Number of open containers"), 2);
    verify(mb, times(1)).addGauge(Interns.info("ClosingContainers", "Number of containers in closing state"), 3);
    verify(mb, times(1)).addGauge(Interns.info("QuasiClosedContainers", "Number of containers in quasi closed state"), 4);
    verify(mb, times(1)).addGauge(Interns.info("ClosedContainers", "Number of containers in closed state"), 5);
    verify(mb, times(1)).addGauge(Interns.info("DeletingContainers", "Number of containers in deleting state"), 6);
    verify(mb, times(1)).addGauge(Interns.info("DeletedContainers", "Number of containers in deleted state"), 7);
}

@Test
public void testNodeReportDispatcher() throws IOException {
    AtomicInteger eventReceived = new AtomicInteger();
    NodeReportProto nodeReport = NodeReportProto.getDefaultInstance();
    NodeManager mockNodeManager = Mockito.mock(NodeManager.class);
    Mockito.when(mockNodeManager.isNodeRegistered(Mockito.any())).thenReturn(true);
    SCMDatanodeHeartbeatDispatcher dispatcher = new SCMDatanodeHeartbeatDispatcher(mockNodeManager, new EventPublisher() {

        @Override
        public <PAYLOAD, EVENT_TYPE extends Event<PAYLOAD>> void fireEvent(EVENT_TYPE event, PAYLOAD payload) {
            Assert.assertEquals(event, NODE_REPORT);
            eventReceived.incrementAndGet();
            Assert.assertEquals(nodeReport, ((NodeReportFromDatanode) payload).getReport());
        }
    });
    DatanodeDetails datanodeDetails = randomDatanodeDetails();
    SCMHeartbeatRequestProto heartbeat = SCMHeartbeatRequestProto.newBuilder().setDatanodeDetails(datanodeDetails.getProtoBufMessage()).setNodeReport(nodeReport).build();
    dispatcher.dispatch(heartbeat);
