@Test
public void filterLog() {
    BaseInsightPoint insightPoint = new BaseInsightPoint() {

        @Override
        public String getDescription() {
            return "test";
        }
    };
    //with simple filter
    Map<String, String> filters = new HashMap<>();
    filters.put("datanode", "123");
    Assert.assertTrue(insightPoint.filterLog(filters, "This a log specific to [datanode=123]"));
    Assert.assertFalse(insightPoint.filterLog(filters, "This a log specific to [datanode=234]"));
    //with empty filters
    Assert.assertTrue(insightPoint.filterLog(new HashMap<>(), "This a log specific to [datanode=234]"));
    //with multiple filters
    filters.clear();
    filters.put("datanode", "123");
    filters.put("pipeline", "abcd");
    Assert.assertFalse(insightPoint.filterLog(filters, "This a log specific to [datanode=123]"));
    Assert.assertTrue(insightPoint.filterLog(filters, "This a log specific to [datanode=123] [pipeline=abcd]"));
    Assert.assertFalse(insightPoint.filterLog(filters, "This a log specific to [datanode=456] [pipeline=abcd]"));
}

