/**
 * Check that no files are actually moved to trash since it is disabled by
 * fs.rename(src, dst, options).
 */
@Test
public void testRenameToTrashDisabled() throws IOException {
    // Create a file
    String testKeyName = "testKey1";
    Path path = new Path(bucketPath, testKeyName);
    try (FSDataOutputStream stream = fs.create(path)) {
        stream.write(1);
    }
    // Call moveToTrash. We can't call protected fs.rename() directly
    trash.moveToTrash(path);
    // Construct paths
    String username = UserGroupInformation.getCurrentUser().getShortUserName();
    Path trashRoot = new Path(bucketPath, TRASH_PREFIX);
    Path userTrash = new Path(trashRoot, username);
    Path userTrashCurrent = new Path(userTrash, "Current");
    Path trashPath = new Path(userTrashCurrent, testKeyName);
    // Trash Current directory should still have been created.
    Assert.assertTrue(ofs.exists(userTrashCurrent));
    // Check under trash, the key should be deleted instead
    Assert.assertFalse(ofs.exists(trashPath));
    // Cleanup
    ofs.delete(trashRoot, true);
}

@Test
public void testFileDelete() throws Exception {
    Path grandparent = new Path(bucketPath, "testBatchDelete");
    Path parent = new Path(grandparent, "parent");
    Path childFolder = new Path(parent, "childFolder");
    // BatchSize is 5, so we're going to set a number that's not a
    // multiple of 5. In order to test the final number of keys less than
    // batchSize can also be deleted.
    for (int i = 0; i < 8; i++) {
        Path childFile = new Path(parent, "child" + i);
        Path childFolderFile = new Path(childFolder, "child" + i);
        ContractTestUtils.touch(fs, childFile);
        ContractTestUtils.touch(fs, childFolderFile);
    }
    assertTrue(fs.listStatus(grandparent).length == 1);
    assertTrue(fs.listStatus(parent).length == 9);
    assertTrue(fs.listStatus(childFolder).length == 8);
    Boolean successResult = fs.delete(grandparent, true);
    assertTrue(successResult);
    assertTrue(!ofs.exists(grandparent));
    for (int i = 0; i < 8; i++) {
        Path childFile = new Path(parent, "child" + i);
        // Make sure all keys under testBatchDelete/parent should be deleted
        assertTrue(!ofs.exists(childFile));
        // Test to recursively delete child folder, make sure all keys under
        // testBatchDelete/parent/childFolder should be deleted.
        Path childFolderFile = new Path(childFolder, "child" + i);
        assertTrue(!ofs.exists(childFolderFile));
    }
    // Will get: WARN  ozone.BasicOzoneFileSystem delete: Path does not exist.
    // This will return false.
    Boolean falseResult = fs.delete(parent, true);
    assertFalse(falseResult);
}

@Test
public void testContainerOpsMetrics() throws IOException {
    MetricsRecordBuilder metrics;
    ContainerManager containerManager = scm.getContainerManager();
    metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
    long numSuccessfulCreateContainers = getLongCounter("NumSuccessfulCreateContainers", metrics);
    ContainerInfo containerInfo = containerManager.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, OzoneConsts.OZONE);
    metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
    Assert.assertEquals(getLongCounter("NumSuccessfulCreateContainers", metrics), ++numSuccessfulCreateContainers);
    try {
        containerManager.allocateContainer(HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, OzoneConsts.OZONE);
        fail("testContainerOpsMetrics failed");
    } catch (IOException ex) {
        // Here it should fail, so it should have the old metric value.
        metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
        Assert.assertEquals(getLongCounter("NumSuccessfulCreateContainers", metrics), numSuccessfulCreateContainers);
        Assert.assertEquals(getLongCounter("NumFailureCreateContainers", metrics), 1);
    }
    metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
    long numSuccessfulDeleteContainers = getLongCounter("NumSuccessfulDeleteContainers", metrics);
    containerManager.deleteContainer(new ContainerID(containerInfo.getContainerID()));
    metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
    Assert.assertEquals(getLongCounter("NumSuccessfulDeleteContainers", metrics), numSuccessfulDeleteContainers + 1);
    try {
        // Give random container to delete.
        containerManager.deleteContainer(new ContainerID(RandomUtils.nextLong(10000, 20000)));
        fail("testContainerOpsMetrics failed");
    } catch (IOException ex) {
        // Here it should fail, so it should have the old metric value.
        metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
        Assert.assertEquals(getLongCounter("NumSuccessfulDeleteContainers", metrics), numSuccessfulCreateContainers);
        Assert.assertEquals(getLongCounter("NumFailureDeleteContainers", metrics), 1);
    }
    containerManager.listContainer(new ContainerID(containerInfo.getContainerID()), 1);
    metrics = getMetrics(SCMContainerManagerMetrics.class.getSimpleName());
    Assert.assertEquals(getLongCounter("NumListContainerOps", metrics), 1);
}

