@Test
public void testVolumeQuotaWithMultiThread() throws IOException, InterruptedException {
    String volumeName = UUID.randomUUID().toString();
    int blockSize = (int) ozoneManager.getConfiguration().getStorageSize(OZONE_SCM_BLOCK_SIZE, OZONE_SCM_BLOCK_SIZE_DEFAULT, StorageUnit.BYTES);
    // Write data larger than one block size.
    String value = generateData(blockSize + 100, (byte) RandomUtils.nextLong()).toString();
    int valueLength = value.getBytes().length;
    long currentQuotaUsage = 0L;
    store.createVolume(volumeName);
    OzoneVolume volume = store.getVolume(volumeName);
    // The initial value should be 0
    Assert.assertEquals(0L, volume.getUsedBytes());
    CountDownLatch latch = new CountDownLatch(2);
    AtomicInteger failCount = new AtomicInteger(0);
    // Multiple threads write different buckets and ensure that the volume
    // quota is correct.
    Runnable r = () -> {
        try {
            for (int i = 0; i < 10; i++) {
                String keyName = UUID.randomUUID().toString();
                String bucketName = UUID.randomUUID().toString();
                volume.createBucket(bucketName);
                OzoneBucket bucket = volume.getBucket(bucketName);
                OzoneOutputStream out = bucket.createKey(keyName, valueLength, STAND_ALONE, ONE, new HashMap<>());
                out.write(value.getBytes());
                out.close();
            }
            latch.countDown();
        } catch (IOException ex) {
            latch.countDown();
            failCount.incrementAndGet();
        }
    };
    Thread thread1 = new Thread(r);
    Thread thread2 = new Thread(r);
    thread1.start();
    thread2.start();
    latch.await(6000, TimeUnit.SECONDS);
    if (failCount.get() > 0) {
        fail("testVolumeQuotaWithMultiThread failed");
    }
    currentQuotaUsage += valueLength * 10 * 2;
    Assert.assertEquals(currentQuotaUsage, store.getVolume(volumeName).getUsedBytes());
}

