@Test
public void testContainerReplication() throws Exception {
    //GIVEN
    long containerId = 1L;
    cluster.waitForClusterToBeReady();
    HddsDatanodeService firstDatanode = cluster.getHddsDatanodes().get(0);
    //copy from the first datanode
    List<DatanodeDetails> sourceDatanodes = new ArrayList<>();
    sourceDatanodes.add(firstDatanode.getDatanodeDetails());
    Pipeline sourcePipelines = MockPipeline.createPipeline(sourceDatanodes);
    //create a new client
    XceiverClientSpi client = new XceiverClientGrpc(sourcePipelines, conf);
    client.connect();
    //New container for testing
    TestOzoneContainer.createContainerForTesting(client, containerId);
    ContainerCommandRequestProto requestProto = writeChunkForContainer(client, containerId, 1024);
    DatanodeBlockID blockID = requestProto.getWriteChunk().getBlockID();
    // Put Block to the test container
    ContainerCommandRequestProto putBlockRequest = ContainerTestHelper.getPutBlockRequest(sourcePipelines, requestProto.getWriteChunk());
    ContainerCommandResponseProto response = client.sendCommand(putBlockRequest);
    Assert.assertNotNull(response);
    Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
    HddsDatanodeService destinationDatanode = chooseDatanodeWithoutContainer(sourcePipelines, cluster.getHddsDatanodes());
    // Close the container
    ContainerCommandRequestProto closeContainerRequest = ContainerTestHelper.getCloseContainer(sourcePipelines, containerId);
    response = client.sendCommand(closeContainerRequest);
    Assert.assertNotNull(response);
    Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
    //WHEN: send the order to replicate the container
    cluster.getStorageContainerManager().getScmNodeManager().addDatanodeCommand(destinationDatanode.getDatanodeDetails().getUuid(), new ReplicateContainerCommand(containerId, sourcePipelines.getNodes()));
    DatanodeStateMachine destinationDatanodeDatanodeStateMachine = destinationDatanode.getDatanodeStateMachine();
    //wait for the replication
    GenericTestUtils.waitFor(() -> destinationDatanodeDatanodeStateMachine.getSupervisor().getReplicationRequestCount() > 0, 1000, 20_000);
    OzoneContainer ozoneContainer = destinationDatanodeDatanodeStateMachine.getContainer();
    Container container = ozoneContainer.getContainerSet().getContainer(containerId);
    Assert.assertNotNull("Container is not replicated to the destination datanode", container);
    Assert.assertNotNull("ContainerData of the replicated container is null", container.getContainerData());
    KeyValueHandler handler = (KeyValueHandler) ozoneContainer.getDispatcher().getHandler(ContainerType.KeyValueContainer);
    BlockData key = handler.getBlockManager().getBlock(container, BlockID.getFromProtobuf(blockID));
    Assert.assertNotNull(key);
    Assert.assertEquals(1, key.getChunks().size());
    Assert.assertEquals(requestProto.getWriteChunk().getChunkData(), key.getChunks().get(0));
}

