@Test
public void testReadRequest() throws Exception {
    String volumeName = "volume" + RandomStringUtils.randomNumeric(5);
    ObjectStore objectStore = getObjectStore();
    objectStore.createVolume(volumeName);
    OMFailoverProxyProvider omFailoverProxyProvider = OmFailoverProxyUtil.getFailoverProxyProvider(objectStore.getClientProxy());
    String currentLeaderNodeId = omFailoverProxyProvider.getCurrentProxyOMNodeId();
    // A read request from any proxy should failover to the current leader OM
    for (int i = 0; i < getNumOfOMs(); i++) {
        // Failover OMFailoverProxyProvider to OM at index i
        OzoneManager ozoneManager = getCluster().getOzoneManager(i);
        // Get the ObjectStore and FailoverProxyProvider for OM at index i
        final ObjectStore store = OzoneClientFactory.getRpcClient(getOmServiceId(), getConf()).getObjectStore();
        final OMFailoverProxyProvider proxyProvider = OmFailoverProxyUtil.getFailoverProxyProvider(store.getClientProxy());
        // Failover to the OM node that the objectStore points to
        omFailoverProxyProvider.performFailoverIfRequired(ozoneManager.getOMNodeId());
        // A read request should result in the proxyProvider failing over to
        // leader node.
        OzoneVolume volume = store.getVolume(volumeName);
        Assert.assertEquals(volumeName, volume.getName());
        Assert.assertEquals(currentLeaderNodeId, proxyProvider.getCurrentProxyOMNodeId());
    }
}

