@Test
public void testOMRatisSnapshot() throws Exception {
    String userName = "user" + RandomStringUtils.randomNumeric(5);
    String adminName = "admin" + RandomStringUtils.randomNumeric(5);
    String volumeName = "volume" + RandomStringUtils.randomNumeric(5);
    String bucketName = "bucket" + RandomStringUtils.randomNumeric(5);
    VolumeArgs createVolumeArgs = VolumeArgs.newBuilder().setOwner(userName).setAdmin(adminName).build();
    ObjectStore objectStore = getObjectStore();
    objectStore.createVolume(volumeName, createVolumeArgs);
    OzoneVolume retVolumeinfo = objectStore.getVolume(volumeName);
    retVolumeinfo.createBucket(bucketName);
    OzoneBucket ozoneBucket = retVolumeinfo.getBucket(bucketName);
    String leaderOMNodeId = OmFailoverProxyUtil.getFailoverProxyProvider(objectStore.getClientProxy()).getCurrentProxyOMNodeId();
    OzoneManager ozoneManager = getCluster().getOzoneManager(leaderOMNodeId);
    // Send commands to ratis to increase the log index so that ratis
    // triggers a snapshot on the state machine.
    long appliedLogIndex = 0;
    while (appliedLogIndex <= getSnapshotThreshold()) {
        createKey(ozoneBucket);
        appliedLogIndex = ozoneManager.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    }
    GenericTestUtils.waitFor(() -> {
        try {
            if (ozoneManager.getRatisSnapshotIndex() > 0) {
                return true;
            }
        } catch (IOException ex) {
            fail("test failed during transactionInfo read");
        }
        return false;
    }, 1000, 100000);
    // The current lastAppliedLogIndex on the state machine should be greater
    // than or equal to the saved snapshot index.
    long smLastAppliedIndex = ozoneManager.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    long ratisSnapshotIndex = ozoneManager.getRatisSnapshotIndex();
    Assert.assertTrue("LastAppliedIndex on OM State Machine (" + smLastAppliedIndex + ") is less than the saved snapshot index(" + ratisSnapshotIndex + ").", smLastAppliedIndex >= ratisSnapshotIndex);
    // Add more transactions to Ratis to trigger another snapshot
    while (appliedLogIndex <= (smLastAppliedIndex + getSnapshotThreshold())) {
        createKey(ozoneBucket);
        appliedLogIndex = ozoneManager.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    }
    GenericTestUtils.waitFor(() -> {
        try {
            if (ozoneManager.getRatisSnapshotIndex() > 0) {
                return true;
            }
        } catch (IOException ex) {
            fail("test failed during transactionInfo read");
        }
        return false;
    }, 1000, 100000);
    // The new snapshot index must be greater than the previous snapshot index
    long ratisSnapshotIndexNew = ozoneManager.getRatisSnapshotIndex();
    Assert.assertTrue("Latest snapshot index must be greater than previous " + "snapshot indices", ratisSnapshotIndexNew > ratisSnapshotIndex);
}

@Test
public void testOMRestart() throws Exception {
    ObjectStore objectStore = getObjectStore();
    // Get the leader OM
    String leaderOMNodeId = OmFailoverProxyUtil.getFailoverProxyProvider(objectStore.getClientProxy()).getCurrentProxyOMNodeId();
    OzoneManager leaderOM = getCluster().getOzoneManager(leaderOMNodeId);
    // Get follower OMs
    OzoneManager followerOM1 = getCluster().getOzoneManager(leaderOM.getPeerNodes().get(0).getOMNodeId());
    OzoneManager followerOM2 = getCluster().getOzoneManager(leaderOM.getPeerNodes().get(1).getOMNodeId());
    // Do some transactions so that the log index increases
    String userName = "user" + RandomStringUtils.randomNumeric(5);
    String adminName = "admin" + RandomStringUtils.randomNumeric(5);
    String volumeName = "volume" + RandomStringUtils.randomNumeric(5);
    String bucketName = "bucket" + RandomStringUtils.randomNumeric(5);
    VolumeArgs createVolumeArgs = VolumeArgs.newBuilder().setOwner(userName).setAdmin(adminName).build();
    objectStore.createVolume(volumeName, createVolumeArgs);
    OzoneVolume retVolumeinfo = objectStore.getVolume(volumeName);
    retVolumeinfo.createBucket(bucketName);
    OzoneBucket ozoneBucket = retVolumeinfo.getBucket(bucketName);
    for (int i = 0; i < 10; i++) {
        createKey(ozoneBucket);
    }
    long lastAppliedTxOnFollowerOM = followerOM1.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    // Stop one follower OM
    followerOM1.stop();
    // Do more transactions. Stopped OM should miss these transactions and
    // the logs corresponding to atleast some of the missed transactions
    // should be purged. This will force the OM to install snapshot when
    // restarted.
    long minNewTxIndex = lastAppliedTxOnFollowerOM + (getLogPurgeGap() * 10);
    long leaderOMappliedLogIndex = leaderOM.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    List<String> missedKeys = new ArrayList<>();
    while (leaderOMappliedLogIndex < minNewTxIndex) {
        missedKeys.add(createKey(ozoneBucket));
        leaderOMappliedLogIndex = leaderOM.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    }
    // Restart the stopped OM.
    followerOM1.restart();
    // Get the latest snapshotIndex from the leader OM.
    long leaderOMSnaphsotIndex = leaderOM.getRatisSnapshotIndex();
    // The recently started OM should be lagging behind the leader OM.
    long followerOMLastAppliedIndex = followerOM1.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    Assert.assertTrue(followerOMLastAppliedIndex < leaderOMSnaphsotIndex);
    // Wait for the follower OM to catch up
    GenericTestUtils.waitFor(() -> {
        long lastAppliedIndex = followerOM1.getOmRatisServer().getLastAppliedTermIndex().getIndex();
        if (lastAppliedIndex >= leaderOMSnaphsotIndex) {
            return true;
        }
        return false;
    }, 100, 200000);
    // Do more transactions. The restarted OM should receive the
    // new transactions. It's last applied tx index should increase from the
    // last snapshot index after more transactions are applied.
    for (int i = 0; i < 10; i++) {
        createKey(ozoneBucket);
    }
    long followerOM1lastAppliedIndex = followerOM1.getOmRatisServer().getLastAppliedTermIndex().getIndex();
    Assert.assertTrue(followerOM1lastAppliedIndex > leaderOMSnaphsotIndex);
}

