@Test
public void testValidateAndUpdateCache() throws Exception {
    OMRequest omRequest = createFileRequest(volumeName, bucketName, keyName, HddsProtos.ReplicationFactor.ONE, HddsProtos.ReplicationType.RATIS, false, true);
    TestOMRequestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    OMFileCreateRequest omFileCreateRequest = new OMFileCreateRequest(omRequest);
    OMRequest modifiedOmRequest = omFileCreateRequest.preExecute(ozoneManager);
    long id = modifiedOmRequest.getCreateFileRequest().getClientID();
    String openKey = omMetadataManager.getOpenKey(volumeName, bucketName, keyName, id);
    // Before calling
    OmKeyInfo omKeyInfo = omMetadataManager.getOpenKeyTable().get(openKey);
    Assert.assertNull(omKeyInfo);
    omFileCreateRequest = new OMFileCreateRequest(modifiedOmRequest);
    OMClientResponse omFileCreateResponse = omFileCreateRequest.validateAndUpdateCache(ozoneManager, 100L, ozoneManagerDoubleBufferHelper);
    Assert.assertEquals(OzoneManagerProtocolProtos.Status.OK, omFileCreateResponse.getOMResponse().getStatus());
    // Check open table whether key is added or not.
    omKeyInfo = omMetadataManager.getOpenKeyTable().get(openKey);
    Assert.assertNotNull(omKeyInfo);
    List<OmKeyLocationInfo> omKeyLocationInfoList = omKeyInfo.getLatestVersionLocations().getLocationList();
    Assert.assertTrue(omKeyLocationInfoList.size() == 1);
    OmKeyLocationInfo omKeyLocationInfo = omKeyLocationInfoList.get(0);
    // Check modification time
    Assert.assertEquals(modifiedOmRequest.getCreateFileRequest().getKeyArgs().getModificationTime(), omKeyInfo.getModificationTime());
    Assert.assertEquals(omKeyInfo.getModificationTime(), omKeyInfo.getCreationTime());
    // Check data of the block
    OzoneManagerProtocolProtos.KeyLocation keyLocation = modifiedOmRequest.getCreateFileRequest().getKeyArgs().getKeyLocations(0);
    Assert.assertEquals(keyLocation.getBlockID().getContainerBlockID().getContainerID(), omKeyLocationInfo.getContainerID());
    Assert.assertEquals(keyLocation.getBlockID().getContainerBlockID().getLocalID(), omKeyLocationInfo.getLocalID());
}

