public void testValidateAndUpdateCacheWithNonRecursive() throws Exception {
    testNonRecursivePath(UUID.randomUUID().toString(), false, false, false);
    testNonRecursivePath("a/b", false, false, true);
    // Create some child keys for the path
    TestOMRequestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/c/d", 0L, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, omMetadataManager);
    TestOMRequestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/c/", 0L, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, omMetadataManager);
    TestOMRequestUtils.addKeyToTable(false, volumeName, bucketName, "a/b/", 0L, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, omMetadataManager);
    TestOMRequestUtils.addKeyToTable(false, volumeName, bucketName, "a/", 0L, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.ONE, omMetadataManager);
    // cannot create file if directory of same name exists
    testNonRecursivePath("a/b/c", false, false, true);
    // Delete child key but retain path "a/b/ in the key table
    omMetadataManager.getKeyTable().delete(omMetadataManager.getOzoneKey(volumeName, bucketName, "a/b/c/d"));
    omMetadataManager.getKeyTable().delete(omMetadataManager.getOzoneKey(volumeName, bucketName, "a/b/c/"));
    // can create non-recursive because parents already exist.
    testNonRecursivePath("a/b/e", false, false, false);
}

