@Test
public void testValidateAndUpdateCache() throws Exception {
    // Add volume, bucket, key entries to DB.
    TestOMRequestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    TestOMRequestUtils.addKeyToTable(true, volumeName, bucketName, keyName, clientID, replicationType, replicationFactor, omMetadataManager);
    OMRequest modifiedOmRequest = doPreExecute(createAllocateBlockRequest());
    OMAllocateBlockRequest omAllocateBlockRequest = new OMAllocateBlockRequest(modifiedOmRequest);
    // Check before calling validateAndUpdateCache. As adding DB entry has
    // not added any blocks, so size should be zero.
    OmKeyInfo omKeyInfo = omMetadataManager.getOpenKeyTable().get(omMetadataManager.getOpenKey(volumeName, bucketName, keyName, clientID));
    List<OmKeyLocationInfo> omKeyLocationInfo = omKeyInfo.getLatestVersionLocations().getLocationList();
    Assert.assertTrue(omKeyLocationInfo.size() == 0);
    OMClientResponse omAllocateBlockResponse = omAllocateBlockRequest.validateAndUpdateCache(ozoneManager, 100L, ozoneManagerDoubleBufferHelper);
    Assert.assertEquals(OzoneManagerProtocolProtos.Status.OK, omAllocateBlockResponse.getOMResponse().getStatus());
    // Check open table whether new block is added or not.
    omKeyInfo = omMetadataManager.getOpenKeyTable().get(omMetadataManager.getOpenKey(volumeName, bucketName, keyName, clientID));
    // Check modification time
    Assert.assertEquals(modifiedOmRequest.getAllocateBlockRequest().getKeyArgs().getModificationTime(), omKeyInfo.getModificationTime());
    // creationTime was assigned at TestOMRequestUtils.addKeyToTable
    // modificationTime was assigned at
    // doPreExecute(createAllocateBlockRequest())
    Assert.assertTrue(omKeyInfo.getCreationTime() <= omKeyInfo.getModificationTime());
    // Check data of the block
    OzoneManagerProtocolProtos.KeyLocation keyLocation = modifiedOmRequest.getAllocateBlockRequest().getKeyLocation();
    omKeyLocationInfo = omKeyInfo.getLatestVersionLocations().getLocationList();
    Assert.assertTrue(omKeyLocationInfo.size() == 1);
    Assert.assertEquals(keyLocation.getBlockID().getContainerBlockID().getContainerID(), omKeyLocationInfo.get(0).getContainerID());
    Assert.assertEquals(keyLocation.getBlockID().getContainerBlockID().getLocalID(), omKeyLocationInfo.get(0).getLocalID());
}

