@Test
public void testNormalizePathsEnabled() throws Exception {
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "/a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "////a/b/c/d"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "////a/b/////c/d"));
    Assert.assertEquals("a/b/c/...../d", validateAndNormalizeKey(true, "////a/b/////c/...../d"));
    Assert.assertEquals("a/b/d", validateAndNormalizeKey(true, "/a/b/c/../d"));
    Assert.assertEquals("a", validateAndNormalizeKey(true, "a"));
    Assert.assertEquals("a/b", validateAndNormalizeKey(true, "/a/./b"));
    Assert.assertEquals("a/b", validateAndNormalizeKey(true, ".//a/./b"));
    Assert.assertEquals("a/", validateAndNormalizeKey(true, "/a/."));
    Assert.assertEquals("b/c", validateAndNormalizeKey(true, "//./b/c/"));
    Assert.assertEquals("a/b/c/d", validateAndNormalizeKey(true, "a/b/c/d/"));
    Assert.assertEquals("a/b/c/...../d", validateAndNormalizeKey(true, "////a/b/////c/...../d/"));
}

