@Test
public void testAddToDBBatch() throws Exception {
    OmKeyInfo omKeyInfo = TestOMRequestUtils.createOmKeyInfo(volumeName, bucketName, keyName, replicationType, replicationFactor);
    OmVolumeArgs omVolumeArgs = OmVolumeArgs.newBuilder().setOwnerName(keyName).setAdminName(keyName).setVolume(volumeName).setCreationTime(Time.now()).build();
    OmBucketInfo omBucketInfo = OmBucketInfo.newBuilder().setVolumeName(volumeName).setBucketName(bucketName).setCreationTime(Time.now()).build();
    OzoneManagerProtocolProtos.OMResponse omResponse = OzoneManagerProtocolProtos.OMResponse.newBuilder().setCommitKeyResponse(OzoneManagerProtocolProtos.CommitKeyResponse.getDefaultInstance()).setStatus(OzoneManagerProtocolProtos.Status.OK).setCmdType(OzoneManagerProtocolProtos.Type.CommitKey).build();
    // As during commit Key, entry will be already there in openKeyTable.
    // Adding it here.
    TestOMRequestUtils.addKeyToTable(true, volumeName, bucketName, keyName, clientID, replicationType, replicationFactor, omMetadataManager);
    String openKey = omMetadataManager.getOpenKey(volumeName, bucketName, keyName, clientID);
    Assert.assertTrue(omMetadataManager.getOpenKeyTable().isExist(openKey));
    String ozoneKey = omMetadataManager.getOzoneKey(volumeName, bucketName, keyName);
    OMKeyCommitResponse omKeyCommitResponse = new OMKeyCommitResponse(omResponse, omKeyInfo, ozoneKey, openKey, omVolumeArgs, omBucketInfo);
    omKeyCommitResponse.addToDBBatch(omMetadataManager, batchOperation);
    // Do manual commit and see whether addToBatch is successful or not.
    omMetadataManager.getStore().commitBatchOperation(batchOperation);
    // When key commit key is deleted from openKey table and added to keyTable.
    Assert.assertFalse(omMetadataManager.getOpenKeyTable().isExist(openKey));
    Assert.assertTrue(omMetadataManager.getKeyTable().isExist(omMetadataManager.getOzoneKey(volumeName, bucketName, keyName)));
}

