@Test
public void testBlockTokenVerifier() throws Exception {
    String tokenBlockID = "101";
    Token<OzoneBlockTokenIdentifier> token = secretManager.generateToken("testUser", tokenBlockID, EnumSet.allOf(AccessModeProto.class), 100);
    OzoneBlockTokenIdentifier btIdentifier = OzoneBlockTokenIdentifier.readFieldsProtobuf(new DataInputStream(new ByteArrayInputStream(token.getIdentifier())));
    // Check basic details.
    Assert.assertTrue(btIdentifier.getOwnerId().equals("testUser"));
    Assert.assertTrue(btIdentifier.getBlockId().equals("101"));
    Assert.assertTrue(btIdentifier.getAccessModes().equals(EnumSet.allOf(AccessModeProto.class)));
    Assert.assertTrue(btIdentifier.getOmCertSerialId().equals(omCertSerialId));
    validateHash(token.getPassword(), btIdentifier.getBytes());
    tokenVerifier.verify("testUser", token.encodeToUrlString(), ContainerProtos.Type.PutBlock, "101");
    String notAllledBlockID = "NotAllowedBlockID";
    LambdaTestUtils.intercept(BlockTokenException.class, "Token for block ID: " + tokenBlockID + " can't be used to access block: " + notAllledBlockID, () -> tokenVerifier.verify("testUser", token.encodeToUrlString(), ContainerProtos.Type.PutBlock, notAllledBlockID));
    // Non block operations are not checked by block token verifier
    tokenVerifier.verify(null, null, ContainerProtos.Type.CloseContainer, null);
}

