    identifier.setStrToSign("AWS4-HMAC-SHA256\n" + "20190221T002037Z\n" + "20190221/us-west-1/s3/aws4_request\n" + "c297c080cce4e0927779823d3fd1f5cae71481a8f7dfc7e18d91851294efc47d");
