@Test
public void testSignToken() throws GeneralSecurityException, IOException {
    String keystore = new File(KEYSTORES_DIR, "keystore.jks").getAbsolutePath();
    String truststore = new File(KEYSTORES_DIR, "truststore.jks").getAbsolutePath();
    String trustPassword = "trustPass";
    String keyStorePassword = "keyStorePass";
    String keyPassword = "keyPass";
    KeyStoreTestUtil.createKeyStore(keystore, keyStorePassword, keyPassword, "OzoneMaster", keyPair.getPrivate(), cert);
    // Create trust store and put the certificate in the trust store
    Map<String, X509Certificate> certs = Collections.singletonMap("server", cert);
    KeyStoreTestUtil.createTrustStore(truststore, trustPassword, certs);
    // Sign the OzoneMaster Token with Ozone Master private key
    PrivateKey privateKey = keyPair.getPrivate();
    OzoneBlockTokenIdentifier tokenId = new OzoneBlockTokenIdentifier("testUser", "84940", EnumSet.allOf(HddsProtos.BlockTokenSecretProto.AccessModeProto.class), expiryTime, cert.getSerialNumber().toString(), MAX_LEN);
    byte[] signedToken = signTokenAsymmetric(tokenId, privateKey);
    // Verify a valid signed OzoneMaster Token with Ozone Master
    // public key(certificate)
    boolean isValidToken = verifyTokenAsymmetric(tokenId, signedToken, cert);
    LOG.info("{} is {}", tokenId, isValidToken ? "valid." : "invalid.");
    // Verify an invalid signed OzoneMaster Token with Ozone Master
    // public key(certificate)
    tokenId = new OzoneBlockTokenIdentifier("", "", EnumSet.allOf(HddsProtos.BlockTokenSecretProto.AccessModeProto.class), expiryTime, cert.getSerialNumber().toString(), MAX_LEN);
    LOG.info("Unsigned token {} is {}", tokenId, verifyTokenAsymmetric(tokenId, RandomUtils.nextBytes(128), cert));
}

@Test
public void testAsymmetricTokenPerf() throws NoSuchAlgorithmException, CertificateEncodingException, NoSuchProviderException, InvalidKeyException, SignatureException {
    final int testTokenCount = 1000;
    List<OzoneBlockTokenIdentifier> tokenIds = new ArrayList<>();
    List<byte[]> tokenPasswordAsym = new ArrayList<>();
    for (int i = 0; i < testTokenCount; i++) {
        tokenIds.add(generateTestToken());
    }
    KeyPair kp = KeyStoreTestUtil.generateKeyPair("RSA");
    // Create Ozone Master certificate (SCM CA issued cert) and key store
    X509Certificate omCert;
    omCert = KeyStoreTestUtil.generateCertificate("CN=OzoneMaster", kp, 30, "SHA256withRSA");
    long startTime = Time.monotonicNowNanos();
    for (int i = 0; i < testTokenCount; i++) {
        tokenPasswordAsym.add(signTokenAsymmetric(tokenIds.get(i), kp.getPrivate()));
    }
    long duration = Time.monotonicNowNanos() - startTime;
    LOG.info("Average token sign time with HmacSha256(RSA/1024 key) is {} ns", duration / testTokenCount);
    startTime = Time.monotonicNowNanos();
    for (int i = 0; i < testTokenCount; i++) {
        verifyTokenAsymmetric(tokenIds.get(i), tokenPasswordAsym.get(i), omCert);
    }
    duration = Time.monotonicNowNanos() - startTime;
    LOG.info("Average token verify time with HmacSha256(RSA/1024 key) " + "is {} ns", duration / testTokenCount);
}

