@Test
public void testParsingMount() {
    String bucketName;
    try {
        bucketName = OFSPath.getTempMountBucketNameOfCurrentUser();
    } catch (IOException ex) {
        Assert.fail("Failed to get the current user name, " + "thus failed to get temp bucket name.");
        // Make javac happy
        bucketName = "";
    }
    // Mount only
    OFSPath ofsPath = new OFSPath("/tmp/");
    Assert.assertEquals("", ofsPath.getAuthority());
    Assert.assertEquals(OFSPath.OFS_MOUNT_TMP_VOLUMENAME, ofsPath.getVolumeName());
    Assert.assertEquals(bucketName, ofsPath.getBucketName());
    Assert.assertEquals("tmp", ofsPath.getMountName());
    Assert.assertEquals("", ofsPath.getKeyName());
    Assert.assertEquals("/tmp", ofsPath.getNonKeyPath());
    Assert.assertTrue(ofsPath.isMount());
    Assert.assertEquals("/tmp/", ofsPath.toString());
    // Mount with key
    ofsPath = new OFSPath("/tmp/key1");
    Assert.assertEquals("", ofsPath.getAuthority());
    Assert.assertEquals(OFSPath.OFS_MOUNT_TMP_VOLUMENAME, ofsPath.getVolumeName());
    Assert.assertEquals(bucketName, ofsPath.getBucketName());
    Assert.assertEquals("tmp", ofsPath.getMountName());
    Assert.assertEquals("key1", ofsPath.getKeyName());
    Assert.assertEquals("/tmp", ofsPath.getNonKeyPath());
    Assert.assertTrue(ofsPath.isMount());
    Assert.assertEquals("/tmp/key1", ofsPath.toString());
}

@Test
public void readToByteBuffer() throws IOException {
    for (IntFunction<ByteBuffer> constructor : BUFFER_CONSTRUCTORS) {
        for (int streamLength = 1; streamLength <= 10; streamLength++) {
            for (int bufferCapacity = 0; bufferCapacity <= 10; bufferCapacity++) {
                testReadToByteBuffer(constructor, streamLength, bufferCapacity, 0);
                if (bufferCapacity > 1) {
                    testReadToByteBuffer(constructor, streamLength, bufferCapacity, 1);
                    if (bufferCapacity > 2) {
                        testReadToByteBuffer(constructor, streamLength, bufferCapacity, bufferCapacity - 1);
                    }
                }
                testReadToByteBuffer(constructor, streamLength, bufferCapacity, bufferCapacity);
            }
        }
    }
}

